using System.Collections; using UnityEngine; using TMPro;  public class DialogueManager : MonoBehaviour {     public GameObject dialoguePanel;     public TMP_Text dialogueText;     [TextArea(2, 5)] public string[] lines;     public float typeSpeed = 0.03f;      int index;     bool isTyping;     Coroutine typingRoutine;      void Awake()     {         dialoguePanel.SetActive(false);     }      void Update()     {         if (!dialoguePanel.activeSelf || !Input.GetKeyDown(KeyCode.Space)) return;          if (isTyping)         {             StopCoroutine(typingRoutine);             dialogueText.text = lines[index];             isTyping = false;             return;         }          index++;         if (index < lines.Length)         {             ShowLine();             return;         }          dialoguePanel.SetActive(false);         Time.timeScale = 1f;     }      public void StartDialogue()     {         Debug.Log("Start Dialogue" + lines.Length);         if (lines.Length == 0)         {             Debug.LogWarning("DialogueManager: lines is empty");             return;         }          index = 0;         dialoguePanel.SetActive(true);         Time.timeScale = 0f;         ShowLine();     }      void ShowLine()     {         if (typingRoutine != null) StopCoroutine(typingRoutine);         typingRoutine = StartCoroutine(TypeLine(lines[index]));     }      IEnumerator TypeLine(string line)     {         Debug.Log("Start typing" + line);         isTyping = true;         dialogueText.text = "";          foreach (char c in line)         {             dialogueText.text += c;             yield return new WaitForSecondsRealtime(typeSpeed);         }          isTyping = false;     } }